pm.test("Verificar que la respuesta sea 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Verificar que el body no esté vacío", function () {
    pm.expect(pm.response.text()).to.include("");
});

pm.test("Verificar que el tiempo de respuesta sea menor a 1000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test("Verificar Content-Type", function () {
    pm.response.to.have.header("Content-Type");
});

pm.test("Verificar tamaño de respuesta", function () {
    pm.expect(pm.response.size().body).to.be.above(0);
});
